(async () => {
'use strict';
const waiting=setTimeout(()=>{const n=document.createElement('p');n.className='notice';n.id='site-startup-note';n.setAttribute('role','status');n.textContent='正在读取项目资料。免费服务休眠后首次打开可能稍慢，请稍候。';document.querySelector('#app')?.prepend(n);},4000);
try { await window.PeachAPI.ready; } catch (error) { document.querySelector('#home-view').hidden=true; const panel=document.querySelector('#secondary-view'); panel.classList.remove('is-hidden'); const message=document.createElement('p'); message.className='notice'; message.textContent='网站资料暂时无法加载：'+error.message;const retry=document.createElement('button');retry.type='button';retry.className='button button-primary';retry.textContent='重新加载资料';retry.onclick=()=>location.reload();panel.append(message,retry); return; }finally{clearTimeout(waiting);document.querySelector('#site-startup-note')?.remove();}
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const home=$('#home-view'),secondary=$('#secondary-view'),modal=$('#app-modal'),modalContent=$('#modal-content');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=window.PeachAPI,survey=window.PeachSurveyData;
const webImages=new Set(['embroidered-ip','fact-crisp-a1','fact-gift-c1','fact-season-b1','ink-peach-branch','ip-sheet','origin-walk','peach-market','sorting-check','xiaotaoman']);
const media=src=>!src?'assets/web/xiaotaoman.webp':/^assets\/[^/]+\.[^.]+$/.test(src)&&webImages.has(src.split('/').pop().replace(/\.[^.]+$/,''))?src.replace(/^assets\//,'assets/web/').replace(/\.[^.]+$/,'.webp'):src;
const state={route:'home',scenario:'family',filter:'scene',fact:'consumer',trace:'origin',ip:'season',ops:'overview',content:'season',records:'all',slide:0,homeGroup:'buy'};
const names={home:'总览',evidence:'事实中心',consumer:'选一箱桃',trace:'批次事实链',ip:'小桃满 IP',operator:'AI+OPC 运营台',content:'内容工作室',rural:'一日桃乡',service:'收货与售后',competition:'赛事讲解',records:api.mode==='server'?'我的记录':'我的演示记录',api:'功能与接口'};
const kinds={consultation:'商品咨询',claim:'售后反馈',tour:'路线意向'},statuses={pending:'待跟进',processing:'处理中',resolved:'演示处理完成'};
const reviewItems=['产地与实际发货地','规格与重量分档','批次库存与可售数量','商品价格与计价单位','收货区域与配送费用','采摘安排与发货窗口','售后规则与对外话术'];
const seed={title:'从分拣台开始，看清这一箱桃',body:'小桃满带你先看果园与分拣记录，再选适合自己的规格。\n5斤大果家庭装：单果约150—200g，策划书参考价65元／箱。参考价不等于实际到手价，运费、库存和当季可售批次需由运营确认。\n下单前请核对产地、采摘安排、分级标准、发货窗口和售后说明。小桃满负责把信息讲清楚，桃农与运营共同确认事实。'};
const groups={
 consumer:{name:'消费者',n:243,source:'01_消费者调研问卷.csv（现行问卷汇总）',note:'C14、C20、C25 为多选题，比例不应相加为100%。C16 是统一5斤情境下的意愿，不能当作实际成交或配送承诺。',metrics:[['C14',['A'],'关注口感、甜度与脆软'],['C14',['B'],'关注新鲜度与到货完好'],['C15',['A','B'],'选择2—3斤尝鲜装或5斤家庭装'],['C16',['A','B'],'5斤情境：最高接受价不超过69元'],['C17',['A','B'],'接受包邮或1—10元配送费'],['C20',['A'],'希望看果园、采摘和分拣实拍'],['C20',['C'],'希望看真实开箱、试吃与评价'],['C20',['G'],'希望看小桃满插画及科普'],['C25',['A'],'因含运费总价超预算而放弃首购']]},
 opc:{name:'学生与 OPC',n:437,source:'02_学生与OPC调研问卷.csv（现行问卷汇总）',note:'437人中351人为在校学生，不能将全体称作学生或专业运营者。B07“无法判断”单列，不并入真实订单经历。',metrics:[['B02',['A','B'],'在校学生'],['B02',['C','D'],'非在校、已开展运营的个人／团队'],['B07',['A','B'],'仅接触知识或未处理真实订单'],['B07',['C','D'],'有真实订单或主要经营经历'],['B07',['D'],'独立或主要负责过经营及售后'],['B07',['E'],'无法判断实践基础']]},
 farmer:{name:'产业端受访者',n:206,source:'附件04 · 上坪镇鹰嘴蜜桃产业农户调研数据',note:'206份包含159户自有果园和47名帮他人打理果树者。第9题是农户转述，不是消费者直接验证。“不会使用”不等于“不愿学习”。',metrics:[['Q02',159,206,'家庭自有果园'],['Q06',199,206,'不会使用线上软件卖桃'],['Q04',157,206,'反映村里无统一运输、包装场所'],['Q08',112,206,'不愿长期统一收果合作'],['Q09',179,195,'农户转述客人看重口感品质'],['Q10',148,198,'提到销售渠道与行情问题'],['Q14',144,189,'希望拓展销售渠道、稳定销路']]}
};
function factRows(key){const g=groups[key],rows=survey[key]||[];return g.metrics.map(m=>{const byOption=Array.isArray(m[1]),count=byOption?rows.filter(r=>r.question===m[0]&&m[1].includes(r.option)).reduce((sum,r)=>sum+r.count,0):m[1],n=byOption?(rows.find(r=>r.question===m[0])?.denominator||g.n):m[2];return {question:m[0],label:m.length===4?m[3]:m[2],count,n,percent:(count/n*100).toFixed(key==='farmer'?2:1)};});}
const btn=(text,action,value='',extra='')=>`<button class="button button-small" type="button" data-action="${action}" data-value="${esc(value)}" ${extra}>${text}</button>`;
const link=(text,route)=>`<button class="button button-quiet" type="button" data-route="${route}">${text} ↗</button>`;
const stamp=v=>new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const empty=(title,copy,route)=>`<div class="empty-state"><img src="assets/web/xiaotaoman.webp" alt=""><b>${title}</b><p>${copy}</p>${route?link('开始体验',route):''}</div>`;
let toastTimer,opener,photoURLs=[],routeToken=0;
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('is-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('is-visible'),3400);}
function head(kicker,title,copy){const page=api.cms?.pages.find(x=>x.id===state.route);return `<div class="view-head"><div><div class="view-kicker">${esc(page?.kicker||kicker)}</div><h2 tabindex="-1">${esc(page?.title||title)}</h2></div><div><p>${esc(page?.intro||copy)}</p><button class="back-link" type="button" data-route="home">← 返回总览</button></div></div>`;}
function shell(k,t,c,body,note='参考方案与演示记录均有状态标识'){const page=api.cms?.pages.find(x=>x.id===state.route);return `<div class="view-shell">${head(k,t,c)}<div class="view-bar"><p>${esc(page?.notice||note)}</p><span class="mode-label"><i></i>${api.mode==='server'?'在线服务 · 数据保存于后台':'项目服务 · 浏览器保存'}</span></div>${body}${page?.body||page?.image?`<details class="compact-details"><summary>更多说明与依据</summary>${page.image?`<img class="cms-page-image" src="${media(page.image)}" alt="补充配图">`:''}<p class="published-copy">${esc(page.body)}</p><small>${esc(page.sourceRef)}</small></details>`:''}<div class="secondary-footer"><span>${esc(api.cms?.settings?.[0]?.slogan||'数商桃乡，让好桃被看见')}</span><div>${link('我的记录','records')}${link('功能与接口','api')}${api.mode==='server'?btn('刷新最新资料','refresh-site'):''}</div></div></div>`;}
function closeMenu(){$('.top-nav').classList.remove('is-open');$('.menu-button').setAttribute('aria-expanded','false');}
function badge(){const count=api.snapshot().records.filter(x=>x.status==='pending').length,el=$('[data-record-count]');if(el){el.textContent=count;el.hidden=!count;}const hint=$('[data-storage-hint]');if(hint)hint.textContent=api.mode==='server'?'在线服务':api.storageAvailable?'项目服务':'暂时无法保存';}
function homeGroup(){const categories=window.PeachHomeGroups||{buy:['consumer','trace','service'],create:['ip','content','operator'],learn:['evidence','rural','competition']};$$('.entry-card').forEach(x=>x.hidden=!(categories[state.homeGroup]||[]).includes(x.dataset.route));$$('[data-home-group]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.homeGroup===state.homeGroup)));}
const renderers={evidence:renderEvidence,consumer:renderConsumer,trace:renderTrace,ip:renderIP,operator:renderOperator,content:renderContent,rural:renderRural,service:renderService,competition:renderCompetition,records:renderRecords,api:renderAPI};
function render(route,focus=false){clearTimeout(toastTimer);$('#toast').classList.remove('is-visible');state.route=Object.hasOwn(names,route)?route:'home';routeToken++;home.classList.toggle('is-hidden',state.route!=='home');secondary.className='secondary-view'+(state.route==='competition'?' competition-page':'')+(state.route==='home'?' is-hidden':'');if(state.route==='home')homeGroup();else{secondary.innerHTML=renderers[state.route]();secondary.classList.remove('screen-enter');void secondary.offsetWidth;secondary.classList.add('screen-enter');}document.title=(api.cms?.settings?.[0]?.brand||'数商桃乡')+' · '+names[state.route];$$('nav [data-route]').forEach(x=>{if(x.dataset.route===state.route)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current');});closeMenu();badge();tabs();window.scrollTo({top:0,behavior:'instant'});if(focus)(state.route==='home'?$('#home-title'):$('.view-head h2'))?.focus({preventScroll:true});window.dispatchEvent(new CustomEvent('peach:route'));if(api.mode==='server'&&state.route==='records'){secondary.setAttribute('aria-busy','true');api.request('GET','/api/records?limit=100').then(()=>{if(state.route==='records'){refresh();secondary.setAttribute('aria-busy','false');}}).catch(err=>{secondary.setAttribute('aria-busy','false');toast('记录刷新失败：'+err.message);});}}
function route(key){const next=Object.hasOwn(names,key)?key:'home';if(location.hash!=='#'+next)history.pushState({},'','#'+next);closeModal();render(next,true);}
function refresh(){const scroll=window.scrollY;if(renderers[state.route]){secondary.innerHTML=renderers[state.route]();tabs();window.scrollTo({top:scroll,behavior:'instant'});}}
function tabs(){$$('[role="tablist"]').forEach(list=>{list.setAttribute('role','group');list.setAttribute('data-tab-group','');$$('button',list).forEach(x=>{x.setAttribute('aria-pressed',String(x.classList.contains('is-active')));x.tabIndex=0;});});}
function renderEvidence(){const g=groups[state.fact];return shell('RESEARCH / 01','每一条结论，都能找到依据。','选择数据集，查看人数、分母和完整选项，也可以导出本组汇总。',`
 <div class="section-toolbar"><div class="tabs" role="tablist" aria-label="调查数据集">${Object.entries(groups).map(([k,v])=>`<button type="button" data-fact="${k}" class="${state.fact===k?'is-active':''}">${v.name} · ${v.n}</button>`).join('')}</div>${btn('导出 CSV','export-facts')}</div>
 <div class="fact-grid"><section class="panel panel-pad"><div class="panel-title"><div><h3>${esc(g.name)}</h3><p>${esc(g.source)}</p></div><span class="status status-evidence">n = ${g.n}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>题号与指标</th><th>人数 / 分母</th><th>比例</th><th>来源</th></tr></thead><tbody>${factRows(state.fact).map(r=>`<tr><td><small>${r.question}</small>${esc(r.label)}</td><td>${r.count} / ${r.n}</td><td><b>${r.percent}%</b></td><td>${btn('明细','question',state.fact+':'+r.question)}</td></tr>`).join('')}</tbody></table></div></section><aside class="fact-note"><h4>结论要有边界</h4><p>${esc(g.note)}</p><p>调查用于安排规格、内容和协作顺序；购买意愿不等于成交，演示也不证明销量或服务改善。</p><div class="source-list"><div class="source-item"><b>消费者回答</b><span>偏好与购买阻力</span></div><div class="source-item"><b>农户转述</b><span>经营者视角</span></div><div class="source-item"><b>访谈材料</b><span>定性观察与口述估计</span></div></div>${btn('访谈如何支撑方案','interview')}</aside></div>`,'现行问卷汇总 + 附件01 / 02 / 04 / 06 · 按题号与样本引用');}
function renderConsumer(){const sc=scenarioData[state.scenario],items=productData.filter(p=>p.id!=='ip-card'&&(state.filter==='all'||state.filter==='scene'&&p.scene===state.scenario||state.filter==='fresh'&&p.category==='fresh'||state.filter==='gift'&&p.category==='gift'));return shell('CHOOSE / 02','选好规格，再问清到手总价。','按家庭、礼赠或团购选择。参考价格、商品信息与履约待确认项在咨询前展示。',`
 <div class="consumer-layout"><aside class="scenario-panel"><span class="eyebrow">小桃满帮你选</span><h3>这箱桃，准备寄给谁？</h3><div class="scenario-list">${Object.entries(scenarioData).map(([k,v],i)=>`<button class="scenario-button ${state.scenario===k?'is-active':''}" type="button" data-scenario="${k}" aria-pressed="${state.scenario===k}"><i>${['家','礼','团'][i]}</i><span><b>${esc(v.title)}</b><small>${esc(v.copy)}</small></span></button>`).join('')}</div><div class="choice-box"><span>当前场景建议</span><b>${sc.product}</b><p>${sc.copy}</p>${btn('咨询这个规格','consult',productData.find(p=>p.name===sc.product).id)}</div></aside><section class="panel catalog"><div class="catalog-head"><div><span class="view-kicker">${sc.title} · ${items.length}款参考</span><h3>先看清，再决定</h3></div><div class="filter-tabs">${[['scene','当前场景'],['all','全部'],['fresh','鲜果'],['gift','礼盒']].map(([k,v])=>`<button type="button" data-filter="${k}" class="${state.filter===k?'is-active':''}" aria-pressed="${state.filter===k}">${v}</button>`).join('')}</div></div><div class="product-grid">${items.map(p=>`<article class="product-card"><div class="product-image"><img src="${media(p.image)}" alt="${esc(p.name)}参考画面" loading="lazy"><span class="product-label">参考规格 · 待核价</span></div><div class="product-body"><span class="product-type">${esc(p.type)}</span><h4>${esc(p.name)}</h4><p>${esc(p.desc)}</p><div class="product-foot"><b>${esc(p.price)}<small>${esc(p.priceNote)}</small></b>${btn('查看与咨询','product',p.id)}</div></div></article>`).join('')}</div><p class="form-note">商品方案来自icanAIOPC。2—3斤尝鲜装为问卷支持的拟试行规格；图片用于说明，不代表当前可售批次。</p></section></div>`,'参考商品 · 暂不接收订单或付款 · 运费与到手总价待按地区确认');}
function renderTrace(){const t=traceData[state.trace];return shell('BATCH / 03','一批桃，每一步都有记录。','批次连接商品、产地素材和售后。示例编号与未知字段逐一分清。',`
 <div class="trace-grid"><section class="panel trace-main"><div class="trace-head"><div><span class="view-kicker">BATCH NOTE</span><h3>小桃满的批次小票</h3></div><span class="status status-demo">示例</span></div><div class="batch-search"><label for="batch-search">查询批次</label><input id="batch-search" value="SP-2026-06" maxlength="60">${btn('查询','batch-search')}</div><div class="batch-meta"><div><span>批次编号</span><b>SP-2026-06</b></div><div><span>状态</span><b>演示编号，非真实采摘记录</b></div><div><span>采摘日期</span><b>待当季填写</b></div></div><div class="trace-steps">${Object.entries(traceData).map(([k,v],i)=>`<button type="button" class="trace-step ${state.trace===k?'is-active':''}" data-trace="${k}" aria-pressed="${state.trace===k}"><span>0${i+1}</span><b>${v[0].split(' / ')[1]}</b><small>${['产地与日期','规格与挑果','运费与时效','售后与回访'][i]}</small></button>`).join('')}</div><div class="trace-detail tab-enter"><b>${t[0]}</b><p>${t[1]}</p><small>${t[2]} · ${t[3]}</small></div></section><aside class="panel panel-pad"><h3>购买前必须补齐</h3><div class="fact-fields">${[['实际产地 / 发货地','均须当批确认'],['采摘日 / 库存','待填写'],['分级 / 重量','按当批分拣记录'],['价格 / 运费','收货地区确认后报价'],['发货 / 售后','购买前明确展示'],['责任 / 素材','桃农确认，运营复核']].map(([k,v])=>`<div class="fact-field"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="action-row">${btn('导出批次小票','export-batch')}${link('选规格','consumer')}</div></aside></div>`,'示例 SP-2026-06 · 无实际采摘日期、库存或配送承诺');}
function voice(k){if(api.mode==='server')return api.cms.ip_series.find(x=>x.id===k)?.voice||'';return {season:'跟我看一段果园日常。画面是哪一天拍的、属于哪一批，我们一起记清楚。',package:'拆箱前先看说明卡：规格、保存方式和售后入口，都留在同一个地方。',social:'想要脆一点，还是送给家人？先说说需要，再确认这一批适不适合。',live:'先别急着拍。把这一批的规格、到手总价和发货安排问清楚。',care:'收到桃先看外箱和果品；遇到问题，把照片和情况一起留给运营。',tour:'先了解果园开放安排，再计划出行。现在可以记录意向，确认后再出发。'}[k];}
function renderIP(){const d=ipData[state.ip];return shell('XIAOTAOMAN / 04','小桃满，陪一箱桃走得更远。','以icanAIOPC角色设计为准：上坪桃林守护人、品牌好物推荐官。角色故事为原创创意，商品事实另行核验。',`
 <div class="ip-layout"><aside class="ip-profile"><img src="assets/web/xiaotaoman.webp" alt="小桃满：桃形角色、草帽与乡土服饰"><div class="ip-profile-copy"><span>XIAOTAOMAN</span><h3>小桃满</h3><p>真诚 · 细致 · 有点俏皮</p><p>讲产地、讲规格，也提醒发货和保存。</p></div></aside><section class="ip-main"><div class="tabs" role="tablist" aria-label="IP栏目">${Object.entries(ipData).map(([k,v])=>`<button type="button" data-ip="${k}" class="${state.ip===k?'is-active':''}">${esc(v.title)}</button>`).join('')}</div><div class="panel panel-pad tab-enter"><div class="ip-detail"><img src="${media(d.image)}" alt="${esc(d.title)}项目素材"><div><b>${esc(d.title)}</b><p>${esc(d.copy)}</p><small>${esc(d.use)}</small><small>${esc(d.owner)}</small></div></div><div class="voice-card"><img src="assets/web/xiaotaoman.webp" alt=""><p>“${voice(state.ip)}”</p></div><div class="action-row">${btn('复制栏目文案','copy-ip')}${btn('写成渠道脚本','compose',state.ip)}${btn('下载这张素材','download-ip')}</div></div><div class="role-grid"><article class="role-card"><span>先讲真实</span><b>事实由人确认</b><p>桃农确认产地与采摘，运营核对规格、价格和履约。</p></article><article class="role-card"><span>再讲故事</span><b>IP 帮助理解与记忆</b><p>礼盒、短视频、社群和导览使用统一角色，商品信息始终完整。</p></article></div><details class="compact-details"><summary>查看角色与素材使用规范</summary><p>以icanAIOPC策划书4.2和项目现有素材为基准。保留桃形、草帽及服饰识别特征。角色故事不替代地方史或产地证据；背景图不作为真实产地证据。不虚构库存、检测或效果。</p>${btn('下载使用说明','ip-guide')}</details></section></div>`,'IP设计资料 · 原创叙事与真实产地资料分别标识');}
const ready=ops=>Math.round(ops.checks.filter(Boolean).length/7*100);
const draftStatus=d=>d?({draft:'草稿待提交',submitted:'已提交演练复核',published:'已生成本地发布记录'}[d.status]):'还没有草稿';
function renderOperator(){const db=api.snapshot(),o=db.ops;let body='';
 if(state.ops==='overview')body=`<div class="kpi-grid"><div class="kpi"><span>待跟进记录</span><b>${db.records.filter(r=>r.status==='pending').length}</b><small>来自你的本地操作</small></div><div class="kpi"><span>演练复核</span><b>${ready(o)}%</b><small>${o.checks.filter(Boolean).length} / 7项</small></div><div class="kpi"><span>本地发布记录</span><b>${o.publications.length}</b><small>未对外发布</small></div></div><div class="workflow-note"><img src="assets/web/xiaotaoman.webp" alt=""><div><h4>${draftStatus(o.draft)}</h4><p>先保存草稿，提交复核，再完成7项演练检查。修改草稿后检查项自动重置。</p><div class="action-row">${btn('开始内容草稿','ops','content')}${btn('咨询与回访','ops','feedback')}</div></div></div>`;
 if(state.ops==='content')body=`<div class="panel-title"><div><h4>内容草稿</h4><p>本地模板整理结构，未调用在线大模型。</p></div><span class="status status-ai">${draftStatus(o.draft)}</span></div><form data-form="draft"><label>标题<input name="title" value="${esc(o.draft?.title||seed.title)}" maxlength="80" required></label><label>正文<textarea name="body" rows="7" maxlength="3000" required>${esc(o.draft?.body||seed.body)}</textarea></label><p class="form-note">来源：icanAIOPC商品方案、附件02、C14 / C20。真实发布前须补齐当季批次事实。</p>${errorBox()}<div class="action-row"><button class="button button-primary" type="submit">保存草稿</button>${btn('恢复模板','draft-template')}${btn('提交复核','submit-review')}</div></form>`;
 if(state.ops==='review')body=`<div class="panel-title"><div><h4>OPC 演练复核</h4><p>勾选仅用于演练，不构成当季事实核验。</p></div><span class="status status-human">${ready(o)}%</span></div><div class="notice">${o.draft?`${esc(o.draft.title)} · 第${o.revision}版 · ${draftStatus(o.draft)}`:'先保存草稿并提交复核，再完成演练检查。'}</div><div class="check-list">${reviewItems.map((v,i)=>`<label><input type="checkbox" data-review="${i}" ${o.checks[i]?'checked':''} ${!o.draft||o.draft.status==='draft'?'disabled':''}><span>${v}<small>责任人核对原始记录；当前仅演练此步骤</small></span></label>`).join('')}</div><div class="readiness"><div><span>演练复核 ${o.checks.filter(Boolean).length} / 7</span><progress value="${ready(o)}" max="100">${ready(o)}%</progress></div>${btn(o.draft?.status==='published'?'查看本地发布记录':'生成本地发布记录',o.draft?.status==='published'?'publication':'publish')}</div><p class="form-note">条件不足时点击会提示缺项；同一版本不会重复生成发布快照。</p>`;
 if(state.ops==='feedback')body=`<div class="panel-title"><div><h4>咨询与回访</h4><p>三类记录分别保存。处理备注写回原记录。</p></div>${link('全部记录','records')}</div>${db.records.length?recordList(db.records.slice(0,4)):empty('等待第一条咨询','提交一次商品咨询，再回来查看和处理。','consumer')}`;
 return shell('OPERATIONS / 05','把一批桃，讲清楚、跟到底。','桃农提供事实，学生承担采集与表达，有经验的运营者审核。AI辅助整理，经营责任由人承担。',`<div class="operator-shell"><aside class="operator-side"><div class="operator-side-head"><span class="operator-avatar"><img src="assets/web/xiaotaoman.webp" alt=""></span><div><b>小桃满运营台</b><small>本地流程演练</small></div></div><div class="operator-nav">${[['overview','经营总览'],['content','内容草稿'],['review','事实复核'],['feedback','咨询回访']].map(([k,v])=>`<button type="button" data-ops="${k}" class="${state.ops===k?'is-active':''}" aria-pressed="${state.ops===k}">${v}</button>`).join('')}</div><p class="operator-side-note">学生先培训、再执行；经验运营者核验、验收并承担经营责任。结算规则在试行前明确。</p></aside><div class="operator-main"><div class="flow">${[['01','采集事实','evidence'],['02','内容整理','content'],['03','人工复核','review'],['04','跟进回访','feedback']].map(([n,t,k])=>`<button type="button" class="flow-node ${state.ops===k?'is-active':''}" ${k==='evidence'?'data-route="evidence"':`data-ops="${k}"`}><span>${n}</span><b>${t}</b></button>`).join('')}</div><div class="tab-enter">${body}</div></div></div>`,'草稿 / 复核 / 发布记录可刷新保留 · 无真实对外发布');}
function renderContent(){const d=ipData[state.content];return shell('CONTENT / 06','真实素材，换一种表达。','一份产地资料进入短视频、直播、社群与随箱卡。每次改写保留来源和人工审核。',`
 <section class="panel panel-pad"><div class="tabs" role="tablist" aria-label="内容主题">${Object.entries(ipData).map(([k,v])=>`<button type="button" data-content="${k}" class="${state.content===k?'is-active':''}">${esc(v.title)}</button>`).join('')}</div><div class="content-workspace"><div class="content-preview"><img src="${media(d.image)}" alt="${esc(d.title)}项目素材"><span>项目素材 · 不代表当季批次</span></div><div><span class="view-kicker">${esc(d.use)}</span><h3>${esc(d.title)}</h3><p>${esc(d.copy)}</p><div class="notice">${esc(d.owner)}<br>实拍与商品事实为主体，小桃满负责解释、提醒和品牌识别。</div><div class="channel-grid">${[['video','短视频脚本'],['live','直播讲解'],['group','社群通知'],['card','随箱说明卡']].map(([k,v])=>btn(v,'compose',state.content+':'+k)).join('')}</div><p class="form-note">可编辑、复制、下载，再保存到运营草稿。传播效果须另行采集。</p></div></div></section><details class="compact-details"><summary>查看试行指标与记录方式</summary><p>短视频记录播放与完播，直播记录有效咨询，商品页记录咨询与转化，售后记录问题类型和处理耗时。演示不预填真实效果。</p>${btn('下载试行记录模板','metric-template')}</details>`,'渠道模板可操作 · 本地结构模板，未调用在线AI');}
function renderRural(){const stops=[['桃园观察','认识花期、套袋和成熟节奏；开放日期、人数和安全条件待确认。'],['分拣体验','认识规格分级与包装；指导人员、时长和卫生规范待确认。'],['集市与礼盒','产地记忆进入礼盒和回访；商品按当季批次确认。']];return shell('PEACH VILLAGE / 07','跟着小桃满，走一趟桃乡。','接待日期、人员与容量待合作方核验。可以记录出行意向，之后再确认。',`
 <div class="rural-layout"><div class="route-map"><div class="route-title"><span>A DAY IN SHANGPING</span><b>一日桃乡</b></div>${['one','two','three'].map((k,i)=>`<button class="route-pin ${k}" type="button" data-action="tour-stop" data-value="${i}"><i></i>${stops[i][0]} ↗</button>`).join('')}<span class="route-line"></span><img src="assets/web/xiaotaoman.webp" alt="小桃满导览形象"></div><section class="panel panel-pad"><span class="view-kicker">看见 → 参与 → 带走</span><h3>先了解，再出发。</h3><div class="tour-stops">${stops.map(([t,c],i)=>`<button type="button" data-action="tour-stop" data-value="${i}"><span>0${i+1}</span><div><b>${t}</b><small>${c}</small></div><em>↗</em></button>`).join('')}</div><div class="notice">当前未开放预约。提交意向不锁定名额、不收费，也不代表果园已接受预约。</div>${btn('记录路线咨询意向','tour-form')}</section></div>`,'路线设计示意 · 未确认开放时间 · 记录意向后等待跟进');}
function renderService(){return shell('CARE / 08','收到桃之后，小桃满还在。','购买前确认规则，签收时留下记录，反馈后继续跟进。售后结果由运营核验。',`
 <div class="service-layout"><aside class="service-intro"><span class="view-kicker">从收到，到回访</span><h3>先说清，再发货。</h3><p>到货时效、损耗和赔付结果须有当批依据。</p><div class="service-steps"><div><b>01 · 购买前</b><span>确认规格、到手总价、发货窗口与售后。</span></div><div><b>02 · 签收时</b><span>检查外箱和果品，留存外箱、面单和照片。</span></div><div><b>03 · 反馈后</b><span>核验后记录处理备注，继续回访。</span></div></div><div class="action-row">${btn('填写售后反馈','claim-form')}${link('查看反馈进度','records')}</div></aside><section class="panel panel-pad"><h3>你可能想先问</h3><div class="faq-list">${[['什么时候发货？','鲜果按成熟度分批采摘。具体日期、区域与运费按可售批次确认；问卷的48小时情境不是配送承诺。'],['收到后如何保存？','先检查外箱和果品，按随箱的当批食用指南保存。没有明确温度与时长时，不用演示文案代替正式指南。'],['有破损或物流问题怎么办？','保留外箱、面单与果品照片，及时联系运营，按购买前公开的批次规则核验。反馈提交不等于已确认赔付。']].map(([t,c],i)=>`<details class="faq-item" ${i===0?'open':''}><summary><span>0${i+1}</span><b>${t}</b><i aria-hidden="true">＋</i></summary><div class="faq-answer"><p>${c}</p></div></details>`).join('')}</div><div class="qr-row">${[['wechat','微信咨询','contact-safe.png'],['douyin','抖音看果园','contact-safe.png'],['xhs','小红书看礼盒','contact-safe.png']].map(([k,t,p])=>`<button class="qr-button" type="button" data-action="social" data-value="${k}"><img src="assets/${p}" alt="${t}二维码"><span><b>${t}</b><span>查看联系说明</span></span></button>`).join('')}</div></section></div>`,'反馈可保存和跟进 · 页面不确认实际退款或赔付');}
let slides=[
 {title:'问题与证据',copy:'199/206名产业端受访者回答不会用线上软件卖桃。消费者希望看真实果园与分拣内容，关注口感、完好度和到手总价。',source:'Q06 · C14 / C20 / C25',route:'evidence',image:'origin-walk.jpeg'},
 {title:'消费者路径',copy:'家庭、礼赠和团购分别推荐；规格、参考价及未知履约条件在咨询前展示。意向保存后进入跟进列表。',source:'C15 / C16 / C17 · icanAIOPC商品方案',route:'consumer',image:'fact-gift-c1.jpg'},
 {title:'IP辅助营销',copy:'小桃满贯穿产地记录、礼盒说明、直播和回访。先展示实拍与商品信息，再用角色帮助理解、记忆和分享。',source:'icanAIOPC 4.2 · C20',route:'ip',image:'xiaotaoman.png'},
 {title:'协作与推广',copy:'学生采集与表达，经验运营者核验。草稿、复核、本地发布与回访已连通；效果需在接入后台后用销售季真实数据检验。',source:'B07 · 附件02 / 06 · 下一销售季待验证',route:'operator',image:'sorting-check.jpeg'}
];
function renderCompetition(){if(state.slide>=slides.length)state.slide=Math.max(0,slides.length-1);const s=slides[state.slide];return shell('PRESENTATION / 09','把项目讲清楚，也把边界讲清楚。','按四步讲解，共同支持文化传播、品牌创意、数字乡村服务和农文旅方向的辅助演示。',`<div class="presentation-tabs" role="tablist" aria-label="讲解步骤">${slides.map((v,i)=>`<button type="button" data-slide="${i}" class="${state.slide===i?'is-active':''}"><span>0${i+1}</span>${esc(v.title)}</button>`).join('')}</div><div class="presentation-stage tab-enter"><div><span class="view-kicker">第${state.slide+1}步 / 共${slides.length}步</span><h3>${esc(s.title)}</h3><p>${esc(s.copy)}</p><small>材料依据：${esc(s.source)}</small><div class="action-row">${link('打开对应页面',s.route)}${btn('复制讲解','copy-slide')}</div></div><img src="${media(s.image.startsWith('assets/')||s.image.startsWith('/')?s.image:'assets/'+s.image)}" alt="${esc(s.title)}项目素材"></div><div class="presentation-controls">${btn('← 上一步','slide-prev')}<span>${state.slide+1} / ${slides.length}</span>${btn('下一步 →','slide-next')}</div><div class="boundary">${api.mode==='server'?'已完成：调研、IP设计、内容后台、意向承接、权限与访问统计。真实订单、支付及物流系统尚未接入；成交、复购及经营效果仍需销售季验证。':'已完成：调研、IP设计与静态本地流程。待接入：订单、支付、库存、物流与权限。待验证：成交、复购、服务效率及经营效果。'}</div>`,'项目讲解 · 支持方向键切换');}
function recordList(list){return `<div class="record-list">${list.map(r=>`<article class="record-card"><div><span class="status status-${r.status==='resolved'?'evidence':'pending'}">${statuses[r.status]}</span><small>${kinds[r.kind]} · ${stamp(r.createdAt)}</small></div><h4>${esc(r.productName||(r.kind==='tour'?'一日桃乡 · '+r.date:'售后反馈'))}</h4><p>${esc(r.name)} · ${esc(r.region)}${r.quantity?' · '+r.quantity+'箱／盒':''}${r.people?' · '+r.people+'人':''}</p>${r.reply?`<p class="record-reply">处理备注：${esc(r.reply)}</p>`:''}<div class="record-bottom"><code>${esc(r.id)}</code>${btn('查看与跟进','record',r.id)}</div></article>`).join('')}</div>`;}
function renderRecords(){const db=api.snapshot(),list=db.records.filter(r=>state.records==='all'||state.records===r.kind);return shell('MY RECORDS','每次操作，都有下文。','查看此浏览器里的咨询、售后与路线意向。进入记录详情可以演练运营跟进。',`<div class="section-toolbar"><div class="tabs" role="tablist" aria-label="记录类型">${[['all','全部'],['consultation','商品咨询'],['claim','售后反馈'],['tour','路线意向']].map(([k,v])=>`<button type="button" data-record-filter="${k}" class="${state.records===k?'is-active':''}">${v} · ${k==='all'?db.records.length:db.records.filter(r=>r.kind===k).length}</button>`).join('')}</div><div class="action-row">${btn('导出演示记录','export-records')}${btn('清空本地演练','confirm-reset')}</div></div>${!api.storageAvailable?'<div class="notice warning">无法持久保存，关闭页面后数据可能丢失，请及时导出。</div>':''}${list.length?recordList(list):empty('这里还没有记录','先咨询一箱桃，或记录一次售后与路线意向。','consumer')}<details class="compact-details"><summary>操作日志 · ${db.logs.length}条</summary><div class="audit-log">${db.logs.length?db.logs.slice(0,15).map(r=>`<p><time>${stamp(r.at)}</time><code>${r.method} ${esc(r.path)}</code><span>本地完成</span></p>`).join(''):'尚无写入操作'}</div></details>`,'仅此设备 / 此浏览器 · 非真实业务数据 · 可导出');}
function renderAPI(){return shell('DEVELOPER / 接口','功能已连通，后台从这里接上。','页面调用统一API适配层。当前实现本地数据与校验，真实后台须实现同样契约并增加服务端权限。',`<div class="api-layout"><section class="panel panel-pad"><h3>接口试运行</h3><p>请求会执行本地实现，写入会产生浏览器体验记录。</p><form data-form="api"><label>接口<select name="endpoint" data-api-select>${api.contract.map(([m,p,t],i)=>`<option value="${i}">${m} ${p} · ${t}</option>`).join('')}</select></label><label>请求路径<input name="path" value="/api/facts?dataset=consumer" maxlength="250" required></label><label>请求体 JSON<textarea name="payload" rows="6">{}</textarea></label><p class="form-note">占位ID请替换成“我的记录”中的本地ID。校验与业务页面一致。</p>${errorBox()}<button class="button button-primary" type="submit">执行本地请求</button></form><div class="api-response"><div><span id="api-status">等待执行</span>${btn('复制响应','copy-api')}</div><pre id="api-output">选择接口，点击执行查看响应。</pre></div></section><aside class="panel panel-pad"><h3>接入约定</h3><div class="fact-fields">${[['响应','{ data, meta }','meta: mode / persisted / requestId / updatedAt'],['失败','{ error: { status, message } }','参数422 · 未找到404 · 状态冲突409'],['未知事实','保持 null / pending','示例库存、运费和时效不转成承诺'],['后端职责','鉴权 · 权限 · 审核 · 幂等','前端校验不能替代服务端核验']].map(([k,v,n])=>`<div class="fact-field"><span>${esc(k)}</span><b>${esc(v)}</b><small>${n}</small></div>`).join('')}</div><div class="action-row">${btn('下载接口说明','api-doc')}${btn('查看接口清单','api-list')}</div><p class="form-note">当前无远端服务器、文件上传或在线模型调用。完整接入说明见BACKEND.md。</p></aside></div>`,'请求可执行 · 写入仅影响浏览器体验 · 开发功能集中在此页');}
function cleanupPhotos(){photoURLs.forEach(URL.revokeObjectURL);photoURLs=[];}
function openModal(html){if(api.mode==='server')html=html.replaceAll('保存后在“我的演示记录”和运营台查看、演练跟进。','提交后可在“我的记录”查看进度，运营在后台处理。').replaceAll('可用演示昵称，无需手机号','填写便于称呼的名字').replaceAll('演示昵称','你的称呼').replaceAll('收货与售后 · 本地反馈','收货与售后 · 问题反馈').replaceAll('照片可在当前弹窗预览，仅保存文件名，未上传图片。正式受理需接入文件存储。','照片提交后会存入项目后台，仅提交者与有权限的运营可查看；服务端会校验图片类型和大小。').replaceAll('本地结构模板','渠道结构模板');if(!modal.open)opener=document.activeElement;cleanupPhotos();modalContent.innerHTML=html;if(!modal.open)modal.showModal();document.body.classList.add('is-locked');$('.modal-box').scrollTop=0;}
function closeModal(){if(modal.open)modal.close();}
function errorBox(){return '<p class="form-error" role="alert" hidden></p>';}
function consent(){if(api.mode==='server')return '<label>联系方式（选填）<input name="contact" maxlength="120" placeholder="便于运营与你确认，不填写完整住址"></label><label class="consent"><input name="consent" type="checkbox" required><span>'+esc(api.cms?.feature_controls?.[0]?.consentText||'同意将本次意向与反馈保存到项目后台用于跟进；不构成订单、预约或赔付确认。')+'</span></label>';return '<label class="consent"><input name="consent" type="checkbox" required><span>仅在此浏览器保存演示记录；不填写真实联系方式或完整地址。</span></label>';}
function formEnd(text){return `${consent()}${errorBox()}<div class="modal-actions"><button class="button button-primary" type="submit">${text}</button>${btn('取消','close')}</div>`;}
function consultation(id){const p=productData.find(p=>p.id===id)||productData[0];openModal(`<span class="view-kicker">小桃满 · 先记下需要</span><h3 id="modal-title">咨询这一箱</h3><p>保存后在“我的演示记录”和运营台查看、演练跟进。</p><form data-form="consultation"><div class="form-grid"><label class="full">参考规格<select name="productId">${productData.filter(p=>p.id!=='ip-card').map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)} · ${esc(x.price)}</option>`).join('')}</select></label><label>数量（箱／盒）<input name="quantity" type="number" min="1" max="999" step="1" value="1" required></label><label>收货地区<input name="region" maxlength="80" placeholder="如：广东深圳" required></label><label class="full">称呼<input name="name" maxlength="40" placeholder="可用演示昵称，无需手机号" required></label><label class="full">想问清什么<textarea name="note" maxlength="800" placeholder="如：送礼时间、运费、包装或口感"></textarea></label></div><div id="quote-preview" class="notice"></div>${formEnd('保存咨询意向')}</form>`);quote();}
function quote(){const f=$('[data-form="consultation"]');if(!f)return;const p=productData.find(x=>x.id===f.elements.productId.value),q=Number(f.elements.quantity.value),n=Number(p.price.replace('¥',''));$('#quote-preview').textContent=Number.isFinite(n)&&Number.isInteger(q)&&q>0&&q<=999?`商品参考小计 ¥${n*q}。${api.cms?.feature_controls?.[0]?.quoteNote||'运费待确认，到手总价尚未确定。这是咨询意向，不是订单。'}`:'售价和运费待确认；到手总价、库存与发货窗口均需运营回复。';}
function product(id){const p=productData.find(p=>p.id===id);openModal(`<span class="view-kicker">${esc(p.type)} · 参考规格</span><h3 id="modal-title">${esc(p.name)}</h3><div class="modal-grid"><img src="${media(p.image)}" alt="${esc(p.name)}参考图"><div class="modal-list">${p.fields.map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}<div><span>产地与批次</span><b>${esc(api.cms?.feature_controls?.[0]?.productOriginNote||'上坪产区示例 · 当季记录待确认')}</b></div><div><span>损耗与售后</span><b>${esc(api.cms?.feature_controls?.[0]?.productCareNote||'按购买前公开的批次规则；签收时留存外箱、面单与照片')}</b></div></div></div><div class="notice">${esc(p.price)}为商品参考价或待核价状态；配送费、加冰方案、库存与发货窗口需另行确认，当前无法给出实际到手总价。</div><div class="modal-actions">${btn('填写咨询意向','consult',id)}${link('看批次字段','trace')}${link('看售后说明','service')}</div>`);}
function tourForm(){const d=new Date(),today=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);openModal(`<span class="view-kicker">一日桃乡 · 意向咨询</span><h3 id="modal-title">记录想去的一天</h3><p>开放条件待确认；这里不生成预约凭证。</p><form data-form="tour"><div class="form-grid"><label>意向日期<input name="date" type="date" min="${today}" required></label><label>同行人数<input name="people" type="number" min="1" max="50" step="1" value="2" required></label><label>称呼<input name="name" maxlength="40" placeholder="演示昵称" required></label><label>出行地区<input name="region" maxlength="80" placeholder="如：河源市区" required></label><label class="full">想体验的内容<textarea name="note" maxlength="800" placeholder="如：亲子观察、分拣体验"></textarea></label></div>${formEnd('保存路线意向')}</form>`);}
function claimForm(){openModal(`<span class="view-kicker">收货与售后 · 本地反馈</span><h3 id="modal-title">把问题说清楚</h3><form data-form="claim"><div class="form-grid"><label>反馈类型<select name="issue"><option value="damage">到货破损</option><option value="shipping">物流与发货</option><option value="storage">保存与食用</option><option value="other">其他问题</option></select></label><label>批次号<input name="batchId" maxlength="50" placeholder="可暂不填"></label><label>称呼<input name="name" maxlength="40" placeholder="演示昵称" required></label><label>收货地区<input name="region" maxlength="80" placeholder="如：广东广州" required></label><label class="full">问题说明<textarea name="note" minlength="5" maxlength="800" placeholder="至少5个字，说明签收情况与问题" required></textarea></label><label class="full">问题照片（最多3张，每张≤5MB）<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div class="photo-preview full" id="photo-preview"></div></div><p class="form-note">照片可在当前弹窗预览，仅保存文件名，未上传图片。正式受理需接入文件存储。</p>${formEnd('保存售后反馈')}</form>`);}
function compose(value){const [key,channel='video',templateId]=value.split(':'),d=ipData[key]||ipData.season,labels={video:'短视频脚本',live:'直播讲解',group:'社群通知',card:'随箱说明卡'};let body=channel==='card'?'小桃满的随箱提醒\n批次号：[当批填写]\n产地与采摘日：[核验后填写]\n净重／个数／分级：[按实填写]\n保存指南：[按当批说明填写]\n破损反馈：留存外箱、面单与果品照片，按批次规则核验。':`${channel==='video'?'镜头1｜带日期的真实素材':channel==='live'?'开场｜先看批次与规格':'社群通知｜'}\n${esc(d.title)}\n${esc(d.copy)}\n小桃满提醒：${voice(key)||voice('season')}\n行动：先核对到手总价、运费与发货窗口，再留下咨询意向。`;const remoteTemplate=window.PeachOnline?.template(key,channel,templateId);if(remoteTemplate)body=remoteTemplate.body;openModal(`<span class="view-kicker">本地结构模板 · ${labels[channel]}</span><h3 id="modal-title">写成一条内容</h3><form data-form="compose"><label>标题<input name="title" maxlength="80" value="${esc(remoteTemplate?.title||d.title+' · '+labels[channel])}" required></label><label>可编辑正文<textarea name="body" rows="9" maxlength="3000" required>${esc(body)}</textarea></label><p class="form-note">未调用在线AI；方括号内容需责任人补齐后才能对外使用。</p>${errorBox()}<div class="modal-actions"><button class="button button-primary" type="submit">保存到运营草稿</button>${btn('复制正文','copy-compose')}${btn('下载文本','download-compose')}</div></form>`);}
function record(id){const r=api.snapshot().records.find(x=>x.id===id);if(!r){toast('这条记录已不存在，请刷新列表。');return;}openModal(`<span class="view-kicker">${kinds[r.kind]} · 本地记录</span><h3 id="modal-title">查看与跟进</h3><div class="modal-list"><div><span>编号</span><b class="break-anywhere">${esc(r.id)}</b></div><div><span>称呼 / 地区</span><b>${esc(r.name)} / ${esc(r.region)}</b></div>${r.productName?`<div><span>规格 / 数量</span><b>${esc(r.productName)} · ${r.quantity}箱／盒</b></div><div><span>运费 / 到手总价</span><b>待真实批次报价</b></div>`:''}${r.date?`<div><span>意向日期 / 人数</span><b>${r.date} / ${r.people}人 · 未确认预约</b></div>`:''}<div><span>说明</span><b>${esc(r.note||'未补充')}</b></div>${r.photoNames?.length?`<div><span>照片文件名</span><b>${r.photoNames.map(esc).join('、')}（未上传）</b></div>`:''}</div><form data-form="record" data-record-id="${esc(id)}"><label>演示跟进状态<select name="status">${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>处理备注<textarea name="reply" maxlength="800" placeholder="完成前至少填写5个字；演示不构成真实发货或赔付承诺">${esc(r.reply)}</textarea></label>${errorBox()}<div class="modal-actions"><button type="submit" class="button button-primary">保存跟进</button>${btn('关闭','close')}</div></form>`);}
function publication(p){openModal(`<span class="view-kicker">本地发布快照 · 未对外发布</span><h3 id="modal-title">${esc(p.title)}</h3><p>第${p.revision}版 · ${stamp(p.createdAt)} · 7项演练复核完成</p><div class="published-copy">${esc(p.body)}</div><p class="form-note">来源：${p.sourceRefs.map(esc).join('；')}。真实发布前须补齐当季信息并由有权限的运营确认。</p>${btn('复制内容','copy-publication')}`);}
async function copy(text,el){try{await navigator.clipboard.writeText(text);window.PeachUI?.copied(el);toast('已复制。');}catch{openModal(`<h3 id="modal-title">复制内容</h3><p>浏览器未允许自动复制，请选中下方文字复制。</p><textarea readonly rows="10">${esc(text)}</textarea>`);$('textarea',modalContent).select();}}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已生成下载文件。');}
function asset(src,name){const a=document.createElement('a');a.href=src;a.download=name;document.body.append(a);a.click();a.remove();toast('已请求下载，请保留项目来源说明。');}
async function busy(el,fn){if(el?.dataset.busy)return;const label=el?.textContent;if(el){el.dataset.busy='true';el.disabled=true;el.setAttribute('aria-busy','true');el.textContent='处理中…';}try{return await fn();}finally{if(el?.isConnected){el.disabled=false;el.removeAttribute('aria-busy');delete el.dataset.busy;el.textContent=label;}}}
async function saveDraft(f){const data=new FormData(f);return api.request('PATCH','/api/ops/tasks/current',{action:'draft',title:data.get('title'),body:data.get('body')});}
async function action(type,value,el){
 if(window.PeachOnline && await window.PeachOnline.action(type,value,el))return;
 if(type==='close'){closeModal();return;}if(type==='ops'){state.ops=value;refresh();return;}
 if(type==='product'){product(value);return;}if(type==='consult'){consultation(value);return;}if(type==='compose'){compose(value);return;}if(type==='record'){record(value);return;}if(type==='tour-form'){tourForm();return;}if(type==='claim-form'){claimForm();return;}
 if(type==='question'){const [key,q]=value.split(':'),g=groups[key],rows=key==='farmer'?(survey[key]?.filter(x=>x.question===q&&x.option!=='summary').length?survey[key].filter(x=>x.question===q&&x.option!=='summary'):factRows(key).filter(x=>x.question===q)):survey[key].filter(x=>x.question===q);openModal(`<span class="view-kicker">${q} · 数据明细</span><h3 id="modal-title">${esc(g.name)}</h3><p>${esc(g.source)}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>选项 / 指标</th><th>人数</th><th>比例</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.dimension?esc(r.dimension)+' · ':''}${esc(r.label)}</td><td>${r.count}</td><td>${r.percent}%</td></tr>`).join('')}</tbody></table></div><p class="form-note">${esc(g.note)}</p>${key==='farmer'?'<p class="form-note">显示已导入的原表选项；Q09是农户对客人的转述。Q09、Q10、Q13、Q14的有效分母分别为195、198、200、189，开放题为提及编码，不要求比例合计100%。Q11成本及Q12运费情境原表保存在后台项目资料档案，不作为当前报价。</p>':''}`);return;}
 if(type==='interview'){openModal(`<span class="view-kicker">定性材料 · 口述边界</span><h3 id="modal-title">访谈如何支撑方案</h3><div class="modal-list"><div><span>附件01 · 河源市民</span><b>理解购买场景与沟通需求，个人经历不能计入团队销量。</b></div><div><span>附件02 · 企业负责人</span><b>分拣、物流与短销售季提示经营约束；48小时冷链讨论不构成配送承诺。投流、产量和运费均为口述估计。</b></div><div><span>附件06 · 30人次记录</span><b>按受访对象、原话和情境引用，与独立访谈可能重合，不简单相加。80／120／150箱采购经历不属于团队交易。</b></div></div><p>访谈口述与问卷比例分开引用，未经账目核验不写成经营实绩。</p>`);return;}
 if(type==='export-facts'){const g=groups[state.fact],cell=x=>'"'+String(x).replace(/"/g,'""')+'"',rows=[['题号','指标','人数','有效分母','比例%','来源','口径'],...factRows(state.fact).map(r=>[r.question,r.label,r.count,r.n,r.percent,g.source,g.note])];download('数商桃乡_'+g.name+'_汇总.csv','\ufeff'+rows.map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');return;}
 if(type==='export-records'){download('数商桃乡_浏览器体验记录.json',JSON.stringify({exportedAt:new Date().toISOString(),notice:'浏览器体验，非真实经营成果',...api.snapshot()},null,2),'application/json');return;}
 if(type==='export-batch'){const r=await api.request('GET','/api/batches/SP-2026-06');download('示例批次_SP-2026-06.json',JSON.stringify(r,null,2),'application/json');return;}
 if(type==='batch-search'){const r=await api.request('GET','/api/batches/'+encodeURIComponent($('#batch-search').value.trim()));openModal(`<span class="view-kicker">批次查询 · 示例</span><h3 id="modal-title">${r.data.batchId}</h3><p>演示编号，非真实采摘记录。未知字段保留null。</p><pre class="payload-preview">${esc(JSON.stringify(r.data,null,2))}</pre>`);return;}
 if(type==='copy-ip'){const d=ipData[state.ip];await copy(d.title+'\n'+d.copy+'\n'+voice(state.ip)+'\n'+d.use+'\n'+d.owner,el);return;}
 if(type==='download-ip'){const d=ipData[state.ip];asset(d.image,d.title+'.'+d.image.split('.').pop());return;}
 if(type==='ip-guide'){download('小桃满_使用说明.txt','来源：icanAIOPC策划书4.2及项目IP素材。\n角色：上坪桃林守护人、品牌好物推荐官。\n语气：真诚、细致、有点俏皮。\n先事实，再场景，再行动。原创故事不替代地方史与产地证据。\n不得虚构库存、检测和营销效果。价格、运费、发货、售后须人工核验。');return;}
 if(type==='copy-compose'||type==='download-compose'){const f=$('[data-form="compose"]'),text=f.elements.title.value+'\n\n'+f.elements.body.value;if(type==='copy-compose')await copy(text,el);else download('小桃满_渠道文案.txt',text);return;}
 if(type==='metric-template'){download('销售季_试行记录模板.csv','\ufeff日期,批次,渠道,内容版本,曝光,完播,有效咨询,成交订单,售后问题,处理耗时,回访反馈,来源备注\r\n','text/csv;charset=utf-8');return;}
 if(type==='draft-template'){const f=$('[data-form="draft"]');f.elements.title.value=seed.title;f.elements.body.value=seed.body;toast('已填入模板，保存后生效。');return;}
 if(type==='submit-review'){const f=$('[data-form="draft"]');if(f&&!f.reportValidity())return;await busy(el,async()=>{if(f)await saveDraft(f);await api.request('PATCH','/api/ops/tasks/current',{action:'submit'});state.ops='review';refresh();toast('已提交，可以开始7项演练检查。');});return;}
 if(type==='publish'){await busy(el,async()=>{const r=await api.request('POST','/api/ops/publish');refresh();publication(r.data);toast('已保存本地发布快照，未对外发布。');});return;}
 if(type==='publication'){const p=api.snapshot().ops.publications[0];if(p)publication(p);else toast('暂无本地发布记录。');return;}
 if(type==='copy-publication'){const p=api.snapshot().ops.publications[0];if(p)await copy(p.title+'\n'+p.body,el);return;}
 if(type==='tour-stop'){const stops=[['桃园观察','观看花期、套袋与成熟记录；开放日期、人数、安全提示和天气条件待确认。'],['小桃满分拣台','了解重量分档与装箱；指导人员、体验时间、卫生规范与参与范围待确认。'],['集市与礼盒','体验连接礼盒与线上回访；规格、价格、运费和售后按当批确认。']],s=stops[Number(value)];openModal(`<span class="view-kicker">一日桃乡 · 路线节点</span><h3 id="modal-title">${s[0]}</h3><p>${s[1]}</p><div class="notice">体验设计示意，当前未确认开放。</div>${btn('记录路线意向','tour-form')}`);return;}
 if(type==='social'){const s={wechat:['微信咨询','contact-safe.png'],douyin:['抖音看果园','contact-safe.png'],xhs:['小红书看礼盒','contact-safe.png']}[value];openModal(`<span class="view-kicker">项目现有社交入口</span><h3 id="modal-title">${s[0]}</h3><p>个人联系二维码已移除，请使用本站商品咨询或售后反馈表单联系运营。</p><img class="social-qr" src="assets/${s[1]}" alt="${s[0]}二维码">${btn('下载联系说明','download-social',value)}`);return;}
 if(type==='download-social'){const p={wechat:'contact-safe.png',douyin:'contact-safe.png',xhs:'contact-safe.png'}[value];asset('assets/'+p,p);return;}
 if(type==='slide-next'||type==='slide-prev'){state.slide=(state.slide+(type==='slide-next'?1:slides.length-1))%slides.length;refresh();return;}
 if(type==='copy-slide'){const s=slides[state.slide];await copy(s.title+'\n'+s.copy+'\n材料依据：'+s.source,el);return;}
 if(type==='confirm-reset'){openModal(`<h3 id="modal-title">清空本地演练记录？</h3><p>将清空此浏览器的咨询、售后、路线意向、草稿、复核及发布记录。项目调研数据和素材仍可使用。</p><div class="modal-actions">${btn('先导出备份','export-records')}${btn('确认清空','reset')}${btn('取消','close')}</div>`);return;}
 if(type==='reset'){api.reset();closeModal();refresh();toast('本地演练记录已清空。');return;}
 if(type==='copy-api'){await copy($('#api-output').textContent,el);return;}
 if(type==='api-doc'){asset('BACKEND.md','数商桃乡_后台接入说明.md');return;}
 if(type==='api-list'){openModal(`<h3 id="modal-title">本地接口清单</h3><div class="endpoint-list">${api.contract.map(([m,p,t])=>`<div><code>${m} ${p}</code><p>${t}</p></div>`).join('')}</div>`);return;}
 toast('未识别该操作，请返回总览重试。');
}
document.addEventListener('click',async e=>{const r=e.target.closest('[data-route]');if(r){e.preventDefault();route(r.dataset.route);return;}const t=e.target.closest('[data-fact],[data-scenario],[data-filter],[data-trace],[data-ip],[data-ops],[data-content],[data-record-filter],[data-slide],[data-home-group]');if(t){const props={fact:'fact',scenario:'scenario',filter:'filter',trace:'trace',ip:'ip',ops:'ops',content:'content',recordFilter:'records',slide:'slide',homeGroup:'homeGroup'};const k=Object.keys(props).find(k=>t.dataset[k]!==undefined),v=t.dataset[k];state[props[k]]=k==='slide'?Number(v):v;if(k==='scenario')state.filter='scene';if(state.route==='home')homeGroup();else refresh();const attr=k.replace(/[A-Z]/g,x=>'-'+x.toLowerCase());$$('[data-'+attr+']').find(x=>x.dataset[k]===v)?.focus({preventScroll:true});return;}const a=e.target.closest('[data-action]');if(a&&!a.disabled){e.preventDefault();try{await action(a.dataset.action,a.dataset.value,a);}catch(err){toast(err.message||'操作未完成，请重试。');}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('[data-form]'))return;e.preventDefault();const submit=$('[type="submit"]',f),error=$('.form-error',f),ticket=routeToken;if(error)error.hidden=true;try{await busy(submit,async()=>{const kind=f.dataset.form,data=Object.fromEntries(new FormData(f));
 if(kind==='draft'){await saveDraft(f);if(ticket===routeToken){refresh();toast('草稿已保存；修改内容会重置复核。');}return;}
 if(kind==='compose'){await api.request('PATCH','/api/ops/tasks/current',{action:'draft',title:data.title,body:data.body,...(api.mode==='server'?{sourceRefs:[ipData[state.content]?.sourceRef||ipData[state.ip]?.sourceRef||'IP栏目与渠道模板；发布前补齐当批依据']}: {})});state.ops='content';route('operator');toast('已存入运营草稿。');return;}
 if(kind==='api'){let payload;try{payload=JSON.parse(data.payload||'{}');}catch{throw Error('请求体不是有效JSON，请检查引号与逗号。');}const [method]=api.contract[Number(data.endpoint)],start=performance.now();try{const r=await api.request(method,data.path,payload);if(ticket===routeToken){$('#api-output').textContent=JSON.stringify(r,null,2);$('#api-status').textContent=`200 · ${api.mode==='server'?'服务端':'本地实现'} · ${Math.round(performance.now()-start)}ms`;}}catch(err){if(ticket===routeToken){$('#api-output').textContent=JSON.stringify({error:{status:err.status||500,message:err.message}},null,2);$('#api-status').textContent=(err.status||500)+' · 请求未通过';}throw err;}return;}
 if(kind==='record'){await api.request('PATCH','/api/records/'+encodeURIComponent(f.dataset.recordId),{status:data.status,reply:data.reply});closeModal();refresh();toast('状态与处理备注已写回原记录。');return;}
 let response;if(kind==='consultation')response=await api.request('POST','/api/consultations',{...data,quantity:Number(data.quantity),consent:data.consent==='on'});
 if(kind==='tour')response=await api.request('POST','/api/tours/inquiries',{...data,people:Number(data.people),routeId:window.PeachOnline?.tourId(),consent:data.consent==='on'});
 if(kind==='claim'){const files=Array.from(f.elements.photos.files);if(files.length>3||files.some(x=>x.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(x.type)))throw Error('最多3张JPG、PNG或WebP图片，每张不超过5MB。');response=await api.request('POST','/api/service/claims',{...data,photoNames:files.map(x=>x.name),...(api.mode==='server'?{files}:{}),consent:data.consent==='on'});}
 if(response){badge();openModal(`<div class="save-success"><span aria-hidden="true">✓</span><h3 id="modal-title">${api.mode==='server'?'已提交到项目后台':'已保存到本地记录'}</h3><p>${kinds[response.data.kind]} · ${esc(response.data.id)}</p><p>${api.mode==='server'?'可在原浏览器“我的记录”查看运营回复。':response.meta.persisted?'刷新后仍可查看。':'无法持久保存，请及时导出。'}${kind==='tour'?'这不是预约确认。':'这不是订单、发货或赔付确认。'}</p><div class="modal-actions">${btn('查看这条记录','record',response.data.id)}${link('全部记录','records')}</div></div>`);}
 });}catch(err){if(error?.isConnected){error.textContent=err.message;error.hidden=false;}else toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.closest('[data-form="consultation"]'))quote();});
document.addEventListener('change',async e=>{const x=e.target;if(x.matches('[data-review]')){x.disabled=true;try{await api.request('PATCH','/api/ops/tasks/current',{action:'review',index:Number(x.dataset.review),checked:x.checked});if(state.route==='operator'&&state.ops==='review'){refresh();$(`[data-review="${x.dataset.review}"]`)?.focus({preventScroll:true});}}catch(err){if(x.isConnected){x.checked=!x.checked;x.disabled=false;}toast(err.message);}return;}
 if(x.matches('[data-api-select]')){const f=x.form,[m,p]=api.contract[Number(x.value)],examples={'/api/consultations':{productId:'fresh-5',quantity:1,name:'演示访客',region:'广东深圳',note:'想确认运费',consent:true},'/api/records/:recordId':{status:'processing',reply:'等待当季批次确认'},'/api/ops/tasks/current':{action:'draft',...seed},'/api/service/claims':{issue:'damage',name:'演示访客',region:'广东广州',note:'果品出现挤压，请协助核对',consent:true},'/api/tours/inquiries':{date:new Date().toISOString().slice(0,10),people:2,name:'演示访客',region:'河源',consent:true}};f.elements.path.value=p;f.elements.payload.value=JSON.stringify(m==='GET'?{}:examples[p]||{},null,2);return;}
 if(x.matches('input[name="photos"]')){cleanupPhotos();const panel=$('#photo-preview');panel.replaceChildren();const files=Array.from(x.files);if(files.length>3||files.some(f=>f.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type))){x.value='';toast('最多3张图片，每张不超过5MB。');return;}for(const f of files){const u=URL.createObjectURL(f);photoURLs.push(u);const fig=document.createElement('figure'),img=document.createElement('img'),cap=document.createElement('figcaption');img.src=u;img.alt='本地图片预览';cap.textContent=f.name;fig.append(img,cap);panel.append(fig);}}});
modal.addEventListener('close',()=>{if(modal.open)return;document.body.classList.remove('is-locked');cleanupPhotos();modalContent.replaceChildren();if(opener?.isConnected)opener.focus({preventScroll:true});else $('.view-head h2')?.focus({preventScroll:true});});
modal.addEventListener('click',e=>{if(e.target===modal)closeModal();});$('.modal-close').addEventListener('click',closeModal);
$('.menu-button').addEventListener('click',()=>{const isOpen=$('.top-nav').classList.toggle('is-open');$('.menu-button').setAttribute('aria-expanded',String(isOpen));});
document.addEventListener('click',e=>{if(!e.target.closest('.topbar'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();const list=e.target.closest('[data-tab-group]');if(list&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const b=$$('button',list),i=b.indexOf(e.target),n=e.key==='Home'?0:e.key==='End'?b.length-1:(i+(e.key==='ArrowRight'?1:b.length-1))%b.length;b[n]?.click();return;}if(state.route==='competition'&&!modal.open&&!e.target.matches('input,textarea,select')&&!list&&['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();action(e.key==='ArrowRight'?'slide-next':'slide-prev');}});
document.addEventListener('pointerdown',e=>{const x=e.target.closest('button');if(!x||x.disabled||matchMedia('(prefers-reduced-motion: reduce)').matches)return;x.classList.remove('is-pressed');void x.offsetWidth;x.classList.add('is-pressed');setTimeout(()=>x.classList.remove('is-pressed'),240);});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1)||'home';if(r!==state.route)render(r);});
window.addEventListener('popstate',()=>{const r=location.hash.slice(1)||'home';if(r!==state.route)render(r);});
window.addEventListener('peach:datachange',()=>{badge();if(api.mode==='server'&&state.route==='records'&&!modal.open)refresh();});
window.addEventListener('peach:externalchange',()=>{badge();if(['operator','records'].includes(state.route)&&!modal.open)refresh();toast('另一标签页更新了演示记录，已同步。');});
if(api.mode!=='server')survey.farmer=factRows('farmer');
if(api.mode!=='server')survey.interview=[{sourceRef:'附件01',type:'qualitative',label:'市民购买场景与沟通需求'},{sourceRef:'附件02',type:'oral_estimate',label:'分拣、物流与经营约束'},{sourceRef:'附件06',type:'qualitative',label:'30人次汇编，可能与独立材料重合，不简单相加'}];
window.TaoyuanApp={state,apiContract:api.contract,connectors:{request:api.request,fetchFacts:d=>api.request('GET','/api/facts?dataset='+encodeURIComponent(d||'consumer')),saveOpsTask:(id,payload)=>api.request('PATCH','/api/ops/tasks/'+id,payload)}};
if(api.mode==='server'){
 if(api.cms.slides.length)slides.splice(0,slides.length,...api.cms.slides);
 window.PeachEnhance({api,state,groups,survey,renderers,shell,btn,link,esc,media,empty,openModal,toast,download,asset,copy,voice,compose});
 window.PeachPresentation?.({api,state,esc,media});
 for(const n of api.cms.navigation||[])names[n.route]=n.title;
 document.addEventListener('peach:refresh',refresh);
}
render(location.hash.slice(1)||'home');

})();
